Here is the commit message:
perf symbol: Look for ImageBase in PE file to compute .text
 offset

Instead of using the file offset in the debug file.

This fixes a regression from 00a3423492bc90be ("perf symbols: Make
dso__load_bfd_symbols() load PE files from debug cache only"), causing
incorrect symbol resolution when debug file have been stripped from
non-debug sections (in which case its .text section is empty and doesn't
have any file position).

The debug files could also be created with a different file alignment,
and have different file positions from the mmap-ed binary, or have the
section reordered.

This instead looks for the file image base, using the corresponding bfd
*ABS* symbols. As PE symbols only have 4 bytes, it also needs to keep
.text section vma high bits.

Signed-off-by: Remi Bernon <rbernon@codeweavers.com>
Fixes: 00a3423492bc90be ("perf symbols: Make dso__load_bfd_symbols() load PE files from debug cache only")
Cc: Alexander Shishkin <alexander.shishkin@linux.intel.com>
Cc: Jiri Olsa <jolsa@redhat.com>
Cc: Nicholas Fraser <nfraser@codeweavers.com>
Cc: Mark Rutland <mark.rutland@arm.com>
Cc: Namhyung Kim <namhyung@kernel.org>
Cc: Peter Zijlstra <peterz@infradead.org>
Link: http://lore.kernel.org/lkml/20210909192637.4139125-1-rbernon@codeweavers.com
Signed-off-by: Arnaldo Carvalho de Melo <acme@redhat.com>

Here is the root cause:
The bug was caused by the reliance on the file position of the `.text` section in the debug file, which could be empty or have different alignments and positions compared to the mmap-ed binary. This led to incorrect symbol resolution when the debug file was stripped of non-debug sections or had reordered sections, resulting in the inability to accurately compute the `text_offset`.

Here is the patch:

 int dso__load_bfd_symbols(struct dso *dso, const char *debugfile)
 {
 	int err = -1;
 	long symbols_size, symbols_count, i;
 	asection *section;
 	asymbol **symbols, *sym;
 	struct symbol *symbol;
 	bfd *abfd;
 	u64 start, len;

 	abfd = bfd_openr(debugfile, NULL);
 	if (!abfd)
 		return -1;

 	if (!bfd_check_format(abfd, bfd_object)) {
 		pr_debug2("%s: cannot read %s bfd file.\n", __func__,
 			  dso->long_name);
 		goto out_close;
 	}

 	if (bfd_get_flavour(abfd) == bfd_target_elf_flavour)
 		goto out_close;

-	section = bfd_get_section_by_name(abfd, ".text");
-	if (section)
-		dso->text_offset = section->vma - section->filepos;
-
 	symbols_size = bfd_get_symtab_upper_bound(abfd);
 	if (symbols_size == 0) {
 		bfd_close(abfd);
 		return 0;
 	}

 	if (symbols_size < 0)
 		goto out_close;

 	symbols = malloc(symbols_size);
 	if (!symbols)
 		goto out_close;

 	symbols_count = bfd_canonicalize_symtab(abfd, symbols);
 	if (symbols_count < 0)
 		goto out_free;

+	section = bfd_get_section_by_name(abfd, ".text");
+	if (section) {
+		for (i = 0; i < symbols_count; ++i) {
+			if (!strcmp(bfd_asymbol_name(symbols[i]), "__ImageBase") ||
+			    !strcmp(bfd_asymbol_name(symbols[i]), "__image_base__"))
+				break;
+		}
+		if (i < symbols_count) {
+			/* PE symbols can only have 4 bytes, so use .text high bits */
+			dso->text_offset = section->vma - (u32)section->vma;
+			dso->text_offset += (u32)bfd_asymbol_value(symbols[i]);
+		} else {
+			dso->text_offset = section->vma - section->filepos;
+		}
+	}
+
 	qsort(symbols, symbols_count, sizeof(asymbol *), bfd_symbols__cmpvalue);

 #ifdef bfd_get_section
 #define bfd_asymbol_section bfd_get_section
 #endif
 	for (i = 0; i < symbols_count; ++i) {
 		sym = symbols[i];
 		section = bfd_asymbol_section(sym);
 		if (bfd2elf_binding(sym) < 0)
 			continue;

 		while (i + 1 < symbols_count &&
 		       bfd_asymbol_section(symbols[i + 1]) == section &&
 		       bfd2elf_binding(symbols[i + 1]) < 0)
 			i++;

 		if (i + 1 < symbols_count &&
 		    bfd_asymbol_section(symbols[i + 1]) == section)
 			len = symbols[i + 1]->value - sym->value;
 		else
 			len = section->size - sym->value;

 		start = bfd_asymbol_value(sym) - dso->text_offset;
 		symbol = symbol__new(start, len, bfd2elf_binding(sym), STT_FUNC,
 				     bfd_asymbol_name(sym));
 		if (!symbol)
 			goto out_free;

 		symbols__insert(&dso->symbols, symbol);
 	}
 #ifdef bfd_get_section
 #undef bfd_asymbol_section
 #endif

 	symbols__fixup_end(&dso->symbols);
 	symbols__fixup_duplicate(&dso->symbols);
 	dso->adjust_symbols = 1;

 	err = 0;
 out_free:
 	free(symbols);
 out_close:
 	bfd_close(abfd);
 	return err;
 }
 #endif


